import{_ as e,o as t,c as h,a4 as r}from"./chunks/framework.BBs01uty.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/hash-table.md","filePath":"algorithms/hash-table.md"}'),s={name:"algorithms/hash-table.md"};function o(p,a,l,i,n,c){return t(),h("div",null,[...a[0]||(a[0]=[r('<h2 id="散列表" tabindex="-1">散列表 <a class="header-anchor" href="#散列表" aria-label="Permalink to &quot;散列表&quot;">​</a></h2><h4 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h4><p>散列表依赖于数组，以key-value形式存储，将key通过散列函数转换成数组下标，再将value存入数组对应下标的内存中</p><img src="https://static001.geekbang.org/resource/image/92/73/92c89a57e21f49d2f14f4424343a2773.jpg" alt="img" style="zoom:50%;"><h4 id="散列函数设计三要求" tabindex="-1">散列函数设计三要求： <a class="header-anchor" href="#散列函数设计三要求" aria-label="Permalink to &quot;散列函数设计三要求：&quot;">​</a></h4><p>1.散列函数计算得到的散列值是一个非负整数</p><p>2.如果 key1 = key2，那 hash(key1) == hash(key2)</p><p>3.如果 key1 ≠ key2，那 hash(key1) ≠ hash(key2)</p><h4 id="散列冲突" tabindex="-1">散列冲突 <a class="header-anchor" href="#散列冲突" aria-label="Permalink to &quot;散列冲突&quot;">​</a></h4><p>如上第三点要求，要想找到不同的key对应的散列值也不一样的散列函数，几乎不可能，这就是散列冲突。而且数组的存储空间有限，也会加大散列冲突的概率</p><p>解决方法：1.开放寻址法 2.链表法</p><h5 id="开放寻址法" tabindex="-1">开放寻址法： <a class="header-anchor" href="#开放寻址法" aria-label="Permalink to &quot;开放寻址法：&quot;">​</a></h5><p>线性探测：</p><p>插入过程：如插入key为x的过程中，经过散列函数生成的数组下标对应的内存已经有内容，则继续向下遍历数组，寻找空地址，若遍历到尾端还未找到，则从头继续遍历，直到找到空地址，存入数据</p><p>查找过程：和插入过程类似，查找的key经过散列函数后对应的内存若有内容，则对比查找的元素和下标为散列值的元素是否相等（对比key是否相同），若相等则为要查找的元素，否则向下遍历，当找到空地址时还没找到，则说明查找的元素不存在</p><p>缺陷：线性探测法其实存在很大问题。当散列表中插入的数据越来越多时，散列冲突发生的可能性就会越来越大，空闲位置会越来越少，线性探测的时间就会越来越久。极端情况下，我们可能需要探测整个散列表，所以最坏情况下的时间复杂度为 O(n)。同理，在删除和查找时，也有可能会线性探测整张散列表，才能找到要查找或者删除的数据。</p><p>改良：二次探测&amp;多重散列</p><p>所谓二次探测，跟线性探测很像，线性探测每次探测的步长是 1，那它探测的下标序列就是 hash(key)+0，hash(key)+1，hash(key)+2……而二次探测探测的步长就变成了原来的“二次方”，也就是说，它探测的下标序列就是 hash(key)+0，hash(key)+12，hash(key)+22……</p><p>所谓双重散列，意思就是不仅要使用一个散列函数。我们使用一组散列函数 hash1(key)，hash2(key)，hash3(key)……我们先用第一个散列函数，如果计算得到的存储位置已经被占用，再用第二个散列函数，依次类推，直到找到空闲的存储位置。</p><p>不管采用哪种探测方法，当散列表中空闲位置不多的时候，散列冲突的概率就会大大提高。为了尽可能保证散列表的操作效率，一般情况下，我们会尽可能保证散列表中有一定比例的空闲槽位。我们用装载因子（load factor）来表示空位的多少。</p><p>装载因子的计算公式是：散列表的装载因子=填入表中的元素个数/散列表的长度</p><h5 id="链表法" tabindex="-1">链表法： <a class="header-anchor" href="#链表法" aria-label="Permalink to &quot;链表法：&quot;">​</a></h5><p>链表法是一种更加常用的散列冲突解决办法，相比开放寻址法，它要简单很多。我们来看这个图，在散列表中，每个“桶（bucket）”或者“槽（slot）”会对应一条链表，所有散列值相同的元素我们都放到相同槽位对应的链表中。</p><img src="https://static001.geekbang.org/resource/image/a4/7f/a4b77d593e4cb76acb2b0689294ec17f.jpg" alt="img" style="zoom:67%;"><p>当插入的时候，我们只需要通过散列函数计算出对应的散列槽位，将其插入到对应链表中即可，所以插入的时间复杂度是 O(1)。当查找、删除一个元素时，我们同样通过散列函数计算出对应的槽，然后遍历链表查找或者删除。那查找或删除操作的时间复杂度是多少呢？</p><p>实际上，这两个操作的时间复杂度跟链表的长度 k 成正比，也就是 O(k)。对于散列比较均匀的散列函数来说，理论上讲，k=n/m，其中 n 表示散列中数据的个数，m 表示散列表中“槽”的个数。</p>',26)])])}const m=e(s,[["render",o]]);export{d as __pageData,m as default};
